import sim, numpy as np

def trace(amp,steps=320):
    s=sim.Sim();
    vals=[]
    for t in range(steps):
        s.data.ctrl[:] = 0
        s.data.ctrl[2]=amp
        s.data.ctrl[7]=amp
        s.step(1)
        vals.append((t,s.pelvis_position()[0],s.pelvis_position()[2],s.torso_up(),s.box_distance_to_pelvis(),s.box_position()[0]))
    for t,px,pz,tu,bd,bx in vals:
        if t in [0,50,100,120,150,180,200,220,240,260,280,300,320-1]:
            print('t',t,'px',px,'pz',pz,'tu',tu,'bd',bd,'bx',bx)
    return s

for amp in [-6,-7,-8,-9,-10,-11,-12]:
    print('---amp',amp)
    tr=trace(amp,320)
